# ---- self-timing: /api/state and the debug report name their own slow phases ----
_PH = threading.local()
def _ph_reset():
    _PH.t = {}
def _ph_add(name, dt):
    d = getattr(_PH, "t", None)
    if d is not None:
        d[name] = d.get(name, 0.0) + dt
def _timed(name, fn):
    def w(*a, **k):
        t0 = time.time()
        try:
            return fn(*a, **k)
        finally:
            _ph_add(name, time.time() - t0)
    return w
